{"file_text":"// Dynamic Island Audio Player Module
export const DynamicIslandPlayer = {
  tracks: [
    {
      title: "Cybernetic Dream",
      artist: "V1R3 // Synthwave",
      url: "https://cdn.pixabay.com/download/audio/2022/05/27/audio_1808fbf756.mp3?filename=synthwave-80s-110055.mp3"
    },
    {
      title: "Neural Lofi Beats",
      artist: "V1R3 // Chill Hop",
      url: "https://cdn.pixabay.com/download/audio/2022/01/18/audio_d0a13f69d2.mp3?filename=lofi-study-112191.mp3"
    },
    {
      title: "Terminal Ambient 2077",
      artist: "V1R3 // Darkspace",
      url: "https://cdn.pixabay.com/download/audio/2022/10/14/audio_993dafb1f2.mp3?filename=chill-drone-121307.mp3"
    }
  ],
  currentIndex: 0,
  isPlaying: false,
  audio: null,
  isExpanded: false,

  init() {
    if (document.getElementById("dynamic-island-container")) return;
    this.injectStyles();
    this.render();
    this.setupAudio();
    this.bindEvents();
  },

  injectStyles() {
    if (document.querySelector('link[href*="dynamicIsland.css"]')) return;
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = "assets/functions/dynamicIsland/dynamicIsland.css";
    document.head.appendChild(link);
  },

  render() {
    const container = document.createElement("div");
    container.id = "dynamic-island-container";
    container.innerHTML = `
      <div id="dynamic-island" class="dynamic-island" role="region" aria-label="Reproductor de música Dynamic Island">
        <!-- Compact State -->
        <div class="island-compact">
          <div class="island-icon" aria-hidden="true">♫</div>
          <div class="island-title-marquee" id="island-compact-title">Cybernetic Dream</div>
          <div class="island-wave" aria-hidden="true">
            <span></span><span></span><span></span>
          </div>
        </div>

        <!-- Expanded State -->
        <div class="island-expanded">
          <div class="island-header">
            <div class="island-track-info">
              <div class="island-art" aria-hidden="true">⚡</div>
              <div class="island-meta">
                <div class="island-song-title" id="island-song-title">Cybernetic Dream</div>
                <div class="island-artist" id="island-artist">V1R3 // Synthwave</div>
              </div>
            </div>
            <button class="island-close-btn" id="island-close-btn" title="Minimizar" aria-label="Minimizar reproductor">×</button>
          </div>

          <div class="island-progress-container">
            <div class="island-progress-bar" id="island-progress-bar">
              <div class="island-progress-fill" id="island-progress-fill"></div>
            </div>
            <div class="island-time-row">
              <span id="island-current-time">0:00</span>
              <span id="island-total-time">0:00</span>
            </div>
          </div>

          <div class="island-controls">
            <button class="island-btn" id="island-prev-btn" title="Anterior" aria-label="Pista anterior">⏮</button>
            <button class="island-btn island-btn-play" id="island-play-btn" title="Reproducir / Pausar" aria-label="Reproducir o Pausar">▶</button>
            <button class="island-btn" id="island-next-btn" title="Siguiente" aria-label="Siguiente pista">⏭</button>
