  setupAudio() {
    this.audio = new Audio();
    this.audio.preload = "metadata";
    this.loadTrack(this.currentIndex);

    this.audio.addEventListener("timeupdate", () => {
      if (!this.audio.duration) return;
      const progressPercent = (this.audio.currentTime / this.audio.duration) * 100;
      const fill = document.getElementById("island-progress-fill");
      if (fill) fill.style.width = `${progressPercent}%`;

      const currTimeEl = document.getElementById("island-current-time");
      if (currTimeEl) currTimeEl.textContent = this.formatTime(this.audio.currentTime);
    });

    this.audio.addEventListener("loadedmetadata", () => {
      const totalTimeEl = document.getElementById("island-total-time");
      if (totalTimeEl) totalTimeEl.textContent = this.formatTime(this.audio.duration);
    });

    this.audio.addEventListener("ended", () => {
      this.nextTrack();
    });
  },

  loadTrack(index) {
    this.currentIndex = index;
    const track = this.tracks[index];
    this.audio.src = track.url;

    const compactTitle = document.getElementById("island-compact-title");
    const songTitle = document.getElementById("island-song-title");
    const artistEl = document.getElementById("island-artist");

    if (compactTitle) compactTitle.textContent = track.title;
    if (songTitle) songTitle.textContent = track.title;
    if (artistEl) artistEl.textContent = track.artist;
  },

  togglePlay() {
    if (this.isPlaying) {
      this.pause();
    } else {
      this.play();
    }
  },

  play() {
    this.audio.play().then(() => {
      this.isPlaying = true;
      const island = document.getElementById("dynamic-island");
      const playBtn = document.getElementById("island-play-btn");
      if (island) island.classList.add("playing");
      if (playBtn) playBtn.textContent = "⏸";
    }).catch(err => {
      console.warn("Audio playback prevented or failed:", err);
    });
  },

  pause() {
    this.audio.pause();
    this.isPlaying = false;
    const island = document.getElementById("dynamic-island");
    const playBtn = document.getElementById("island-play-btn");
    if (island) island.classList.remove("playing");
    if (playBtn) playBtn.textContent = "▶";
  },

  nextTrack() {
    const nextIdx = (this.currentIndex + 1) % this.tracks.length;
    this.loadTrack(nextIdx);
    if (this.isPlaying) this.play();
  },

  prevTrack() {
    const prevIdx = (this.currentIndex - 1 + this.tracks.length) % this.tracks.length;
    this.loadTrack(prevIdx);
    if (this.isPlaying) this.play();
  },

  seek(e) {
    const bar = document.getElementById("island-progress-bar");
    if (!bar || !this.audio.duration) return;
    const rect = bar.getBoundingClientRect();
    const pos = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    this.audio.currentTime = pos * this.audio.duration;
  },

  formatTime(secs) {
    if (isNaN(secs)) return "0:00";
    const mins = Math.floor(secs / 60);
    const remaining = Math.floor(secs % 60);
    return `${mins}:${remaining < 10 ? '0' : ''}${remaining}`;
  },

  expand() {
    this.isExpanded = true;
    const island = document.getElementById("dynamic-island");
    if (island) island.classList.add("expanded");
  },

  collapse() {
    this.isExpanded = false;
    const island = document.getElementById("dynamic-island");
    if (island) island.classList.remove("expanded");
  },

  bindEvents() {
    const island = document.getElementById("dynamic-island");
    const closeBtn = document.getElementById("island-close-btn");
    const playBtn = document.getElementById("island-play-btn");
    const nextBtn = document.getElementById("island-next-btn");
    const prevBtn = document.getElementById("island-prev-btn");
    const progressBar = document.getElementById("island-progress-bar");

    if (island) {
      island.addEventListener("click", (e) => {
        if (!this.isExpanded && !e.target.closest("button")) {
          this.expand();
        }
      });
    }

    if (closeBtn) {
      closeBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.collapse();
      });
    }

    if (playBtn) {
      playBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.togglePlay();
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.nextTrack();
      });
    }

    if (prevBtn) {
      prevBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        this.prevTrack();
      });
    }

    if (progressBar) {
      progressBar.addEventListener("click", (e) => {
        e.stopPropagation();
        this.seek(e);
      });
    }

    // Collapse when clicking outside
    document.addEventListener("click", (e) => {
      const container = document.getElementById("dynamic-island-container");
      if (this.isExpanded && container && !container.contains(e.target)) {
        this.collapse();
      }
    });
  }
};

// Auto-initialize on load
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", () => DynamicIslandPlayer.init());
} else {
  DynamicIslandPlayer.init();
}
