import json
import websockets
from winsdk.windows.media.control import GlobalSystemMediaTransportControlsSessionManager as MediaManager

async def get_media_info():
    try:
        sessions = await MediaManager.request_async()
        current_session = sessions.get_current_session()
        if current_session:
            info = await current_session.try_get_media_properties_async()
            playback_info = current_session.get_playback_info()
            return {
                "title": info.title or "Desconocido",
                "artist": info.artist or "Spotify / Sistema",
                "isPlaying": playback_info.playback_status.value == 4 if playback_info else True
            }
    except Exception as e:
        print("Error getting media:", e)
    return None

async def handler(websocket, path):
    print("Cliente web conectado al puente de medios.")
    try:
        while True:
            media = await get_media_info()
            if media:
                await websocket.send(json.dumps(media))
            await asyncio.sleep(1.5)
    except websockets.exceptions.ConnectionClosed:
        print("Cliente web desconectado.")

async def main():
    print("Iniciando puente multimedia de Windows en ws://localhost:8765...")
    async with websockets.serve(handler, "localhost", 8765):
        await asyncio.Future()  # run forever

if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        print("Puente detenido.")
